__MCP_managed_ids = {[1]=true} __MCP_managed_deal = false if __MCP_orig_IAP == nil then   __MCP_orig_IAP = IsAutoPropose   IsAutoPropose = function()     if __MCP_managed_deal then return false end     return __MCP_orig_IAP()   end end if __MCP_orig_SWD == nil then   __MCP_orig_SWD = DealManager.SendWorkingDeal   DealManager.SendWorkingDeal = function(action, fromP, toP)     if __MCP_managed_ids[toP] or __MCP_managed_ids[fromP] then       if action == 7 then         print("MCPDEAL|INSPECT|suppressed|from="          .. tostring(fromP) .. "|to=" .. tostring(toP))         return       end       if action == 4 then         print("MCPDEAL|PROPOSED|from=" .. tostring(fromP)           .. "|to=" .. tostring(toP))         local pDeal = DealManager.GetWorkingDeal(          0, fromP, toP)         if pDeal then           for item in pDeal:Items() do             local iType = item:GetType()             local typeName = "UNKNOWN"             if iType == DealItemTypes.GOLD then               typeName = "GOLD"             elseif iType == DealItemTypes.RESOURCES then               typeName = "RESOURCE"             elseif iType == DealItemTypes.AGREEMENTS then               typeName = "AGREEMENT"             elseif iType == DealItemTypes.FAVOR then               typeName = "FAVOR"             elseif iType == DealItemTypes.CITIES then               typeName = "CITY"             elseif iType == DealItemTypes.GREATWORK then               typeName = "GREAT_WORK"             end             print("MCPDEAL_ITEM|" .. typeName               .. "|from=" .. tostring(item:GetFromPlayerID())               .. "|amount=" .. tostring(item:GetAmount())               .. "|duration=" .. tostring(item:GetDuration())               .. "|value=" .. tostring(item:GetValueType() or -1)               .. "|sub=" .. tostring(item:GetSubType() or -1))           end         end         print("MCPDEAL_END")         return       end     end     return __MCP_orig_SWD(action, fromP, toP)   end   print("DEALSHIM|installed") else   print("DEALSHIM|present") end print("---END---")